package uncivai

import com.unciv.json.json
import com.unciv.logic.civilization.AlertType
import com.unciv.logic.civilization.PopupAlert
import uncivai.player.PlayerAlert
import uncivai.player.PlayerHost
import uncivai.player.TurnCommandKind
import uncivai.player.TurnCommandReceipt
import uncivai.player.TurnCommandRequest
import java.nio.file.Path

/** First contact is generated by native loading, not appended by the restore test. */
object AlertCheckpointProbe {
    private val civilizations = listOf("Rome", "Greece")

    @JvmStatic
    fun main(args: Array<String>) {
        val root = Path.of(args.single())
        verifyRestart(root.resolve("restart"))
        verifyRewind(root.resolve("rewind"))
        verifyDiscoveryReward(root.resolve("discovery"))
        verifyInvalidAlerts(root.resolve("invalid"))
    }

    private fun prepare(runtime: HeadlessRuntime): Map<String, List<PlayerAlert>> {
        // Adjacent scouts will meet when loading rebuilds visibility. Model a save
        // from before contact was processed, with both observed and unread alerts.
        for (civilization in civilizations.map(runtime.game::getCivilization)) {
            civilization.diplomacy.clear()
            civilization.popupAlerts.clear()
            civilization.notifications.clear()
        }
        val player = runtime.game.getCivilization("Rome")
        player.popupAlerts.add(PopupAlert(AlertType.StartIntro, ""))
        player.popupAlerts.add(PopupAlert(AlertType.TechResearched, "Agriculture"))
        val before = observations(runtime)
        check(before.getValue("Rome").map { it.handle } == listOf("alert1", "alert2"))
        check(before.getValue("Greece").isEmpty())
        player.popupAlerts.add(PopupAlert(AlertType.GoldenAge, ""))
        return before
    }

    private fun observations(runtime: HeadlessRuntime): Map<String, List<PlayerAlert>> {
        val host = PlayerHost(runtime)
        return civilizations.associateWith { host.bindPlayer(it).turn().alerts }
    }

    private fun verifyLoaded(runtime: HeadlessRuntime, before: Map<String, List<PlayerAlert>>): Map<String, List<PlayerAlert>> {
        val after = observations(runtime)
        val roman = after.getValue("Rome")
        val greek = after.getValue("Greece")
        val expected = before.getValue("Rome").map { it.copy(canAcknowledge = !runtime.executor.isPaused()) }
        check(roman.take(expected.size) == expected) { "Loading changed saved alert content or handles" }
        check(roman.map { it.handle } == listOf("alert1", "alert2", "alert3", "alert4"))
        check(roman[2].kind == "GoldenAge") { "The unread saved alert was lost" }
        check(roman.last().firstContact?.civilizationId == "Greece")
        check(greek.single().let { it.handle == "alert1" && it.firstContact?.civilizationId == "Rome" })
        return after
    }

    private fun verifyRestart(root: Path) {
        val checkpoint = root.resolve("checkpoint.json")
        lateinit var before: Map<String, List<PlayerAlert>>
        lateinit var after: Map<String, List<PlayerAlert>>
        lateinit var request: TurnCommandRequest
        lateinit var receipt: TurnCommandReceipt
        HeadlessRuntime.createDuel(root.resolve("initial"), closeStarts = true).use { runtime ->
            before = prepare(runtime)
            runtime.executor.enableCheckpoints(checkpoint)
        }
        HeadlessRuntime.loadCheckpoint(checkpoint, root.resolve("loaded")).use { runtime ->
            after = verifyLoaded(runtime, before)
        }
        HeadlessRuntime.loadCheckpoint(checkpoint, root.resolve("reloaded")).use { runtime ->
            check(observations(runtime) == after) { "A second load changed handles or duplicated first contact" }
            val session = PlayerHost(runtime).bindPlayer("Rome")
            val turn = session.turn()
            request = TurnCommandRequest("ack-load-contact", turn.epoch, turn.revision, TurnCommandKind.ACKNOWLEDGE_ALERT, after.getValue("Rome").last().handle)
            receipt = session.execute(request)
            after = after + ("Rome" to after.getValue("Rome").dropLast(1))
            check(observations(runtime) == after) { "Acknowledging the new alert consumed a saved alert" }
        }
        HeadlessRuntime.loadCheckpoint(checkpoint, root.resolve("replay")).use { runtime ->
            check(observations(runtime) == after)
            check(PlayerHost(runtime).bindPlayer("Rome").execute(request) == receipt)
            check(observations(runtime) == after)
        }
    }

    private fun verifyRewind(root: Path) {
        val checkpoint = root.resolve("checkpoint.json")
        lateinit var after: Map<String, List<PlayerAlert>>
        HeadlessRuntime.createDuel(root.resolve("initial"), closeStarts = true).use { runtime ->
            val before = prepare(runtime)
            runtime.executor.enableCheckpoints(checkpoint)
            runtime.executor.scheduled = true
            runtime.executor.pause()
            runtime.executor.communicationPaused = true
            val boundary = runtime.executor.turnSnapshot()
            repeat(2) { attempt ->
                runtime.executor.restoreTurn(boundary, "alert-rewind-$attempt")
                after = verifyLoaded(runtime, before)
            }
        }
        HeadlessRuntime.loadCheckpoint(checkpoint, root.resolve("reloaded")).use { runtime ->
            check(observations(runtime) == after) { "Restart lost alerts generated during turn rewind" }
        }
    }

    private fun verifyInvalidAlerts(root: Path) {
        HeadlessRuntime.createDuel(root.resolve("initial"), closeStarts = true).use { runtime ->
            prepare(runtime)
            val saved = CheckpointStore.capture(runtime.game, runtime.epoch, false, runtime.executor.turnSessions)
            for (mode in listOf("missing", "reordered", "changed", "request-id", "missing-handles", "extra-handles")) {
                val loaded = runtime.game.clone().apply { setTransients() }
                val alerts = loaded.getCivilization("Rome").popupAlerts
                when (mode) {
                    "missing" -> alerts.removeAt(0)
                    "reordered" -> java.util.Collections.swap(alerts, 0, 1)
                    "changed" -> alerts[0].value = "Changed during load"
                    "request-id" -> alerts[0].requestId = "different-request"
                }
                val original = saved.players.getValue("Rome")
                val state = when (mode) {
                    "missing-handles" -> original.copy(alertHandles = original.alertHandles.dropLast(1))
                    "extra-handles" -> original.copy(alertHandles = original.alertHandles + listOf(null))
                    else -> original
                }
                GameExecutor(loaded).use { executor ->
                    CheckpointStore(root.resolve("$mode.json")).use { store ->
                        store.writeInitial(saved.copy(players = saved.players + ("Rome" to state)))
                        val failure = runCatching { executor.restore(store.read(), store) }.exceptionOrNull()
                        val expected = if (mode.endsWith("handles")) "Checkpoint alert state is inconsistent" else "Loading changed saved alerts"
                        check(failure is IllegalStateException && failure.message == expected) { "Accepted or misdiagnosed $mode alerts: $failure" }
                    }
                }
            }
        }
    }

    private fun verifyDiscoveryReward(root: Path) {
        val checkpoint = root.resolve("checkpoint.json")
        var initialGold = 0
        lateinit var before: Map<String, List<PlayerAlert>>
        lateinit var normalizedGame: String
        HeadlessRuntime.createDuel(root.resolve("initial"), closeStarts = true).use { runtime ->
            before = prepare(runtime)
            val player = runtime.game.getCivilization("Rome")
            val other = runtime.game.getCivilization("Greece")
            // A newly visible wonder has not yet been processed by the visibility cache.
            val tile = player.viewableTiles.first { it.isLand && !it.isCityCenter() && it.getFirstUnit() == null && it !in other.viewableTiles && it.naturalWonder == null }
            tile.naturalWonder = "El Dorado"
            tile.setTerrainTransients()
            check("El Dorado" !in player.naturalWonders)
            initialGold = player.gold
            runtime.executor.enableCheckpoints(checkpoint)
        }
        HeadlessRuntime.loadCheckpoint(checkpoint, root.resolve("loaded")).use { runtime ->
            verifyLoaded(runtime, before)
            val player = runtime.game.getCivilization("Rome")
            check("El Dorado" in player.naturalWonders && player.gold > initialGold) { "Loading lost the native discovery reward" }
            normalizedGame = json().toJson(runtime.game)
        }
        HeadlessRuntime.loadCheckpoint(checkpoint, root.resolve("reloaded")).use { runtime ->
            check(json().toJson(runtime.game) == normalizedGame) { "Reloading duplicated a discovery event or reward" }
        }
    }
}
